from __future__ import annotations

import asyncio
import re
import time
from collections import deque
from typing import Any

import httpx2

from ds.settings import get_settings
from ds.util import graphql

__all__ = [
    "API_URL",
    "DEVELOPER_SETTINGS_URL",
    "MAX_OBJECTS_PER_REQUEST",
    "MAX_REQUESTS_PER_MINUTE",
    "SITE_URL",
    "TOKEN_LIFETIME_DAYS",
    "ComplexityError",
    "MissingTokenError",
    "RateLimitError",
    "StartggError",
    "gql",
]

# ds::external-source: checked 2026-11-15 https://developer.start.gg/docs/sending-requests
#   taken from it: endpoint
# ds::external-source: checked 2026-11-15 https://developer.start.gg/docs/authentication
#   taken from it: bearer header, token expiry
API_URL = "https://api.start.gg/gql/alpha"
# a slug from the API (tournament/<name>/event/<name>, user/<id>) after this is its page
SITE_URL = "https://www.start.gg"
# ds::external-source: checked 2026-11-15 https://developer.start.gg/docs/rate-limits
#   taken from it: both limits, error bodies
# start.gg's limits (the three numbers every error message below quotes):
MAX_REQUESTS_PER_MINUTE = 80  # per token, averaged over 60 s; _wait_for_budget stays under it
MAX_OBJECTS_PER_REQUEST = 1000  # objects in one response, nested ones included ("complexity")
TOKEN_LIFETIME_DAYS = 365  # a token stops working a year after it was created
DEVELOPER_SETTINGS_URL = "https://start.gg/admin/profile/developer"

MAX_PARALLEL = 4  # requests in flight at once

_RATE_WINDOW = 60.0
_ACTUAL_RE = re.compile(r"actual:\s*(\d+)")
_request_times: deque[float] = deque()
_HTTP_UNAUTHORIZED = 401
_HTTP_RATE_LIMITED = 429


class StartggError(RuntimeError):
    """start.gg refused or failed a request; the message says why"""


class MissingTokenError(StartggError):
    """No start.gg API token is stored"""


class RateLimitError(StartggError):
    """Over MAX_REQUESTS_PER_MINUTE (80 requests per 60 s, per token); wait a minute

    This client paces itself under the limit, so seeing this means something else is using
    the same token at the same time (another process, the API explorer).
    """


class ComplexityError(StartggError):
    """The query would return more than MAX_OBJECTS_PER_REQUEST (1000) objects

    `actual` is start.gg's own count for the request. Fix: ask for fewer rows per page
    (`per_page`) or select fewer nested fields in queries.py.
    """

    def __init__(self, message: str, actual: int | None) -> None:
        super().__init__(message)
        self.actual = actual


def _token() -> str:
    token = get_settings().startgg_api_token
    if token is None:
        raise MissingTokenError(
            " ".join(
                [
                    f"no start.gg API token stored: create one at {DEVELOPER_SETTINGS_URL},",
                    "then run `ds settings sync --guide`",
                ]
            )
        )
    return token.get_secret_value()


async def _wait_for_budget() -> None:
    """Hold a request back while the last 60 s already hold the allowed number"""
    while True:
        now = time.monotonic()
        while _request_times and now - _request_times[0] > _RATE_WINDOW:
            _request_times.popleft()
        if len(_request_times) < MAX_REQUESTS_PER_MINUTE:
            _request_times.append(now)
            return
        await asyncio.sleep(_RATE_WINDOW - (now - _request_times[0]) + 0.05)


def _raise_for_body(status: int, body: Any) -> None:
    """Turn start.gg's error bodies into typed errors (see Site notes for the shapes)"""
    message = body.get("message", "") if isinstance(body, dict) else ""
    errors = body.get("errors") if isinstance(body, dict) else None
    if errors:
        message = "; ".join(str(e.get("message", e)) for e in errors)
    if "rate limit" in message.lower() or status == _HTTP_RATE_LIMITED:
        raise RateLimitError(
            " ".join(
                [
                    f"start.gg rate limit hit: at most {MAX_REQUESTS_PER_MINUTE} requests per 60 s per token",
                    f"({message or status}). Wait a minute; check nothing else is using the same token.",
                ]
            )
        )
    if "complexity" in message.lower():
        found = _ACTUAL_RE.search(message)
        actual = int(found.group(1)) if found else None
        raise ComplexityError(
            " ".join(
                [
                    f"start.gg refused the query: it would return {actual or 'more than the allowed'} objects,",
                    f"the limit is {MAX_OBJECTS_PER_REQUEST} per request (nested objects count).",
                    "Ask for fewer rows per page (per_page).",
                ]
            ),
            actual,
        )
    if status == _HTTP_UNAUTHORIZED or "authentication" in message.lower():
        raise StartggError(
            " ".join(
                [
                    f"start.gg rejected the API token ({message or status}).",
                    f"Tokens expire {TOKEN_LIFETIME_DAYS} days after they are created:",
                    f"make a new one at {DEVELOPER_SETTINGS_URL} and store it with `ds settings sync`.",
                ]
            )
        )
    if errors or status >= httpx2.codes.BAD_REQUEST or (isinstance(body, dict) and body.get("success") is False):
        raise StartggError(f"start.gg request failed (HTTP {status}): {message or body}")


async def gql(
    query: str,
    variables: dict[str, Any] | None = None,
    *,
    client: httpx2.AsyncClient | None = None,
) -> dict[str, Any]:
    """Run one GraphQL query against start.gg and return its `data`

    Sent and logged by ds.util.graphql (kind 'graphql', source 'startgg'); this adds the token,
    the request budget (its wait is the record's `wait_ms`) and start.gg's typed errors.

    Args:
        query: the GraphQL document (see queries.py).
        variables: its variables, eg {"id": 158026}.
        client: reuse one AsyncClient across many calls (api.py does, for paging).
    """
    token = _token()
    start = time.perf_counter()
    await _wait_for_budget()
    result = await graphql.gql(
        API_URL,
        query,
        variables,
        source="startgg",
        headers={"Authorization": f"Bearer {token}"},
        # start.gg's count of objects in the response, the number its 1000 limit is about
        extensions={"objects": "queryComplexity"},
        fields={"wait_ms": round((time.perf_counter() - start) * 1000)},
        check=lambda r: _raise_for_body(r.status, r.body),
        client=client,
    )
    return result.data or {}
